import sys
from typing import TextIO


def column_sums(stream: TextIO) -> list[str]:
    names = stream.readline().strip().split(",")
    sums = [0] * len(names)
    for line in stream:
        line = line.strip()
        if not line:
            continue
        for i, value in enumerate(line.split(",")):
            sums[i] += int(value)
    return [f"{name}: {total}" for name, total in zip(names, sums)]


for line in column_sums(sys.stdin):
    print(line)

