#include <iostream>
#include <sstream>
#include <string>
#include <vector>

std::vector<std::string> columnSums(std::istream& in) {
    std::string line;
    std::string cell;
    std::getline(in, line);
    std::istringstream header(line);
    std::vector<std::string> names;
    while (std::getline(header, cell, ',')) {
        names.push_back(cell);
    }
    std::vector<int> sums(names.size(), 0);
    while (std::getline(in, line)) {
        std::istringstream row(line);
        for (size_t i = 0; i < sums.size() && std::getline(row, cell, ','); i++) {
            sums[i] += std::stoi(cell);
        }
    }
    std::vector<std::string> result;
    for (size_t i = 0; i < names.size(); i++) {
        result.push_back(names[i] + ": " + std::to_string(sums[i]));
    }
    return result;
}

int main() {
    for (const std::string& line : columnSums(std::cin)) {
        std::cout << line << "\n";
    }
    return 0;
}

