package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func columnSums(scanner *bufio.Scanner) []string {
	scanner.Scan()
	names := strings.Split(strings.TrimSpace(scanner.Text()), ",")
	sums := make([]int, len(names))
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		for i, value := range strings.Split(line, ",") {
			n, _ := strconv.Atoi(value)
			sums[i] += n
		}
	}
	result := make([]string, len(names))
	for i, name := range names {
		result[i] = fmt.Sprintf("%s: %d", name, sums[i])
	}
	return result
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	for _, line := range columnSums(scanner) {
		fmt.Println(line)
	}
}
